/**
 * What going live costs.
 *
 * ── THIS IS A PLACEHOLDER UNTIL SOMEBODY CONFIRMS IT ───────────────────────
 * The landing page's promise is "the website is free, you only pay for
 * hosting", so there has to be a number on the checkout screen. $12/month is a
 * stand-in, declared once, here. Change it here and the checkout, the summary
 * and the Stripe fallback all move together.
 *
 * ── STRIPE IS THE REAL SOURCE OF TRUTH ─────────────────────────────────────
 * When STRIPE_PRICE_ID is set, the checkout session is created against that
 * Price and THIS FILE IS ONLY WHAT THE SCREEN SAYS. Prices belong in Stripe,
 * where they can be changed without a deploy and where the charge actually
 * comes from — a price hard-coded in a repo is one that eventually disagrees
 * with the one being billed.
 */

import { TIERS, tierById } from "../data/plans"

/**
 * Prices — MTC-FCS-017.
 * ============================================================================
 * The tiers and what is in them are described in `src/data/plans.js`; this
 * file is the money side of them and the one place a price is read from.
 *
 * ── EVERY PRICE HERE IS A PLACEHOLDER UNTIL SIGNED OFF ─────────────────────
 * Free / $19.99 / $24.99 came from the brief and have not been confirmed by
 * anybody who can confirm them. Set STRIPE_PRICE_ID_PREMIUM and
 * STRIPE_PRICE_ID_LEADS and Stripe owns them, which is where prices belong:
 * changeable without a deploy, and the same number that is actually charged.
 *
 * ── THE SERVER PICKS THE PRICE, NOT THE BROWSER ────────────────────────────
 * `planById` is a whitelist. The checkout route looks a TIER ID up here and
 * never takes an amount from a request, because a price that arrives from a
 * browser is a price anybody can edit.
 */

export const PLANS = TIERS

/** The paid tier the standalone /buy screen sells. */
export const DEFAULT_PAID_PLAN = TIERS.premium

/** Anything unrecognised is the free tier — never an error, never an upgrade. */
export function planById(id) {
  return tierById(id)
}

/* Said where the address is CHOSEN — FCS-059. The worry it answers ("am I
   stuck on a freecontractorservices.com address forever?") arrives while
   somebody is typing this field, and an unanswered worry at that moment is a
   checkout nobody finishes. Phrased as a later step, because that is what it
   is: the site goes live on this address today and the domain moves onto it
   whenever they are ready. */
export const CUSTOM_DOMAIN_NOTE =
  "You can point your own domain at this site later — already have one, or want us to get you one? " +
  "Go live first and we will set that up for you."

export function formatMoney(cents, currency = "usd") {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: currency.toUpperCase(),
    minimumFractionDigits: cents % 100 === 0 ? 0 : 2,
  }).format(cents / 100)
}
