import * as React from "react"
import { Link, navigate } from "gatsby"
import Header from "../components/Header"
import Seo from "../components/Seo"
import { ArrowRight, Check } from "../components/Icons"
import { CUSTOM_DOMAIN_NOTE, DEFAULT_PAID_PLAN, formatMoney } from "../config/pricing"
import { levelsForTier } from "../data/plans"
import { accessToken, useAuth } from "../context/auth"
import { configured } from "../lib/supabase"
import { slugify, slugProblem } from "../lib/slug"
import { loadDraft } from "../lib/site-draft"
import * as s from "../components/auth/Auth.module.css"
import * as b from "../components/Buy.module.css"
import { apiUrl } from "../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../config/supabase-public"

/**
 * Buy now — MTC-FCS-008.
 * ============================================================================
 * The standalone purchase screen, separate from the builder's own checkout
 * step. Somebody who already has an account and already knows what they want
 * should not have to walk back through six questions to pay.
 *
 * ── IT REQUIRES AN ACCOUNT, AND SAYS SO BEFORE ASKING FOR ANYTHING ─────────
 * A subscription needs an owner: without one there is nobody to email a
 * receipt to, nobody to cancel it, and no way to answer "is this site mine?"
 * later. The screen puts that in front rather than letting somebody fill the
 * form and then bounce them.
 *
 * ── NO CARD FIELDS HERE EITHER ─────────────────────────────────────────────
 * Same rule as the builder's checkout: the card is only ever typed on
 * Stripe's own page. This screen collects the address the site will live at
 * and hands off.
 */
const BuyPage = () => {
  const { user, ready, available } = useAuth()

  const [slug, setSlug] = React.useState("")
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState("")

  // If they built a site already, that address is the obvious default.
  React.useEffect(() => {
    const draft = loadDraft()
    const fromDraft = draft?.slug || slugify(draft?.business?.name || "")
    if (fromDraft) setSlug(fromDraft)
  }, [])

  const slugError = slug ? slugProblem(slug) : null
  const signedIn = Boolean(user)

  const submit = async e => {
    e.preventDefault()
    if (busy || !signedIn || slugError || !slug) return
    setBusy(true)
    setError("")

    try {
      const token = await accessToken()
      const res = await fetch(apiUrl("create-checkout-session"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          apikey: SUPABASE_PUBLISHABLE_KEY,
          Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
        },
        body: JSON.stringify({
          billing: { email: user.email },
          site: { subdomain: slug, businessName: "" },
          plan: DEFAULT_PAID_PLAN.id,
          returnTo: "purchase",
        }),
      })
      const data = await res.json().catch(() => ({}))

      if (res.ok && data.url) {
        window.location.href = data.url
        return
      }
      setError(data.message || "Checkout could not be started. Please try again.")
      setBusy(false)
    } catch {
      setError("We could not reach the payment service. Check your connection and try again.")
      setBusy(false)
    }
  }

  return (
    <>
      <Header />
      <main className={b.page} data-print="hide">
        <div className="container">
          <div className={b.head}>
            <h1 className={b.title}>Put your website online</h1>
            <p className={b.lead}>
              The website itself is free. Hosting is what you pay for, and you can cancel it
              whenever you like.
            </p>
          </div>

          <div className={b.layout}>
            <section className={b.panel}>
              {!ready ? (
                <p className={s.loading}>Loading…</p>
              ) : !available ? (
                <p className={s.error} style={{ marginTop: 0 }}>
                  Accounts are not set up on this environment, so nothing can be purchased yet.
                </p>
              ) : !signedIn ? (
                <div className={b.gate}>
                  <h2 className={b.panelTitle}>You need an account first</h2>
                  <p className={b.gateLead}>
                    A subscription needs an owner — somebody to send the receipt to, and somebody
                    who can cancel it. It takes about a minute.
                  </p>
                  <div className={b.gateActions}>
                    <Link to="/sign-up?next=/buy" className="btn btn--lg">
                      Create an account
                      <ArrowRight className="btn__arrow" />
                    </Link>
                    <button
                      type="button"
                      className={s.signOut}
                      onClick={() => navigate("/log-in?next=/buy")}
                    >
                      I already have one
                    </button>
                  </div>
                </div>
              ) : (
                <form onSubmit={submit}>
                  <h2 className={b.panelTitle}>Your website address</h2>
                  <p className={b.gateLead}>
                    This is where your site will live. It is fixed once you pay.
                  </p>

                  <div className={b.slugRow}>
                    <input
                      id="buy-slug"
                      value={slug}
                      onChange={e => setSlug(slugify(e.target.value))}
                      placeholder="your-business"
                      maxLength={50}
                      aria-label="Your website address"
                      aria-invalid={slugError ? "true" : undefined}
                    />
                    <span>.freecontractorservices.com</span>
                  </div>
                  {slugError ? <p className={s.error}>{slugError}</p> : null}
                  <p className={b.domainNote}>{CUSTOM_DOMAIN_NOTE}</p>

                  <p className={b.signedAs}>
                    Buying as <strong>{user.email}</strong>. The receipt goes here.
                  </p>

                  <button
                    type="submit"
                    className={`btn btn--lg ${s.submit}`}
                    disabled={busy || !slug || Boolean(slugError)}
                  >
                    {busy ? "Starting checkout…" : "Continue to secure payment"}
                    {!busy && <ArrowRight className="btn__arrow" />}
                  </button>

                  <p className={b.secure}>
                    You will be taken to Stripe to pay. We never see or store your card details.
                  </p>

                  {error ? <p className={s.error}>{error}</p> : null}
                </form>
              )}
            </section>

            <aside className={b.summary}>
              <p className={b.summaryTitle}>What you get</p>
              <div className={b.priceRow}>
                <span>{DEFAULT_PAID_PLAN.name}</span>
                <strong>
                  {formatMoney(DEFAULT_PAID_PLAN.amount, DEFAULT_PAID_PLAN.currency)}
                  <em>/{DEFAULT_PAID_PLAN.interval}</em>
                </strong>
              </div>
              <div className={b.priceRow}>
                <span>Website design</span>
                <strong className={b.free}>Free</strong>
              </div>

              <ul className="checks" style={{ marginTop: 18 }}>
                {levelsForTier(DEFAULT_PAID_PLAN.id).flatMap(level => level.items).map(item => (
                  <li key={item.id} style={{ fontSize: 13.5 }}>
                    <Check />
                    {item.label}
                  </li>
                ))}
              </ul>

              <p className={b.note}>
                Not built your site yet? <Link to="/website-builder">Start there instead</Link> —
                it is free and you only reach this screen at the end.
              </p>
            </aside>
          </div>
        </div>
      </main>
    </>
  )
}

export const Head = () => (
  <Seo
    title="Put your website online"
    description="Your contracting website is free to build. Pay only for hosting, and cancel whenever you like."
  />
)

export default BuyPage
